(() => {
  const NAMES = new Set(["人物资料 - 伤痕【鸣潮】","人物资料 - 残星会会长【鸣潮】","人物资料 - 娜波摩【鸣潮】","人物资料 - 阿维狄亚【鸣潮】","人物资料 - 克里斯托弗【鸣潮】","人物资料 - 蜜芽【鸣潮】","人物资料 - 织星【鸣潮】","人物资料 - 玉露【鸣潮】","人物资料 - 女性漂泊者与阿布【鸣潮】","人物资料 - 哥舒临【鸣潮】","人物资料 - 莫特斐【鸣潮】","人物资料 - 渊武【鸣潮】","人物资料 - 灯灯【鸣潮】","人物资料 - 桃祈【鸣潮】","人物资料 - 散华【鸣潮】","人物资料 - 炽霞【鸣潮】","人物资料 - 白芷【鸣潮】","人物资料 - 釉瑚【鸣潮】","人物资料 - 秧秧【鸣潮】","人物资料 - 维里奈【鸣潮】","人物资料 - 秋水【鸣潮】","人物资料 - 椿【鸣潮】","人物资料 - 安可【鸣潮】","人物资料 - 卜灵【鸣潮】","人物资料 - 露帕【鸣潮】","人物资料 - 珂莱塔【鸣潮】","人物资料 - 守岸人【鸣潮】","人物资料 - 鉴心【鸣潮】","人物资料 - 嘉贝莉娜【鸣潮】","人物资料 - 菲比【鸣潮】","人物资料 - 夏空【鸣潮】","人物资料 - 赞妮【鸣潮】","人物资料 - 洛可可【鸣潮】","人物资料 - 坎特蕾拉·翡萨烈【鸣潮】","人物资料 - 弗洛洛【鸣潮】","人物资料 - 奥古斯塔【鸣潮】","人物资料 - 布兰特【鸣潮】","人物资料 - 陆·赫斯【鸣潮】","人物资料 - 洛瑟菈【鸣潮】","人物资料 - 绯雪【鸣潮】","人物资料 - 今汐【鸣潮】","人物资料 - 长离【鸣潮】","人物资料 - 忌炎【鸣潮】","人物资料 - 相里要【鸣潮】","人物资料 - 折枝【鸣潮】","人物资料 - 仇远【鸣潮】","人物资料 - 景燃【鸣潮】","人物资料 - 琳奈【鸣潮】","人物资料 - 莫宁【鸣潮】","人物资料 - 西格莉卡【鸣潮】","人物资料 - 千咲【鸣潮】","人物资料 - 穗穗【鸣潮】","人物资料 - 清宵【鸣潮】","人物资料 - 「心」【鸣潮】","人物资料 - 锁暝【鸣潮】","人物资料 - IRIS【鸣潮】","人物资料 - 特莉丝【鸣潮】","人物资料 - 失亡彼岸的奥第那镇民【鸣潮】","人物资料 - 查特【鸣潮】","人物资料 - 罗斯玛丽【鸣潮】","人物资料 - 玛格烈特【鸣潮】","人物资料 - 辛夷【鸣潮】","人物资料 - 凯尔梅尔【鸣潮】","人物资料 - 霍德【鸣潮】","人物资料 - 扎希拉【鸣潮】","人物资料 - 艾露娜【鸣潮】","人物资料 - 梧黎【鸣潮】","人物资料 - 伏翎【鸣潮】","反派资料 - 魏尔伦【鸣潮】","人物资料 - 玄渺真人【鸣潮】","人物资料 - 安瑟姆【鸣潮】","人物资料 - 严彦【鸣潮】","人物资料 - 娜斯塔霞【鸣潮】","反派资料 - 伊摩尔【鸣潮】","人物资料 - 萨迦【鸣潮】","人物资料 - 柯布·科波【鸣潮】","人物资料 - 盖泽尔【鸣潮】","反派资料 - 木禺【鸣潮】","人物资料 - 椋羽【鸣潮】","人物资料 - 秋鸿【鸣潮】","人物资料 - 钱坤【鸣潮】","人物资料 - 铃坊【鸣潮】","人物资料 - 若云与小玉【鸣潮】","人物资料 - 静微真人【鸣潮】","人物资料 - 鲙娘【鸣潮】","人物资料 - 帕斯卡【鸣潮】","人物资料 - 塞维【鸣潮】","人物资料 - 吟霖【鸣潮】","人物资料 - 尤诺【鸣潮】"]);
  const CONDITION = "['索拉里斯','鸣潮'].includes(_.get(getMessageVar('stat_data',{defaults:{}}),'系统配置.世界观',''))";
  const OPEN = '<%_ if(' + CONDITION + '){ _%>';
  const CLOSE = '<%_ } _%>';
  const NEW_OPEN = '<%- ' + CONDITION + ' ? ';
  const NEW_CLOSE = " : '' %>";
  let busy = false;
  const nameOf = e => e.name || e.comment || '';
  const idOf = e => e.uid ?? e.id;
  function separate(s) {
    if (typeof s !== 'string') return null;
    if (s.startsWith(NEW_OPEN) && s.endsWith(NEW_CLOSE)) {
      try {
        const body = JSON.parse(s.slice(NEW_OPEN.length, -NEW_CLOSE.length));
        if (typeof body !== 'string' || body.includes('<%') || body.includes('%>')) return null;
        return {body, mode: 'expression', content: body};
      } catch (_) { return null; }
    }
    let body = s, mode = '';
    if (body.startsWith(OPEN + '\r\n')) { body = body.slice(OPEN.length + 2); mode = 'pair'; }
    else if (body.startsWith(OPEN + '\n')) { body = body.slice(OPEN.length + 1); mode = 'pair'; }
    else if (body.startsWith(OPEN)) { body = body.slice(OPEN.length); mode = 'pair'; }
    if (body.endsWith('\r\n' + CLOSE)) { body = body.slice(0, -(CLOSE.length + 2)); mode = mode || 'orphan-close'; }
    else if (body.endsWith('\n' + CLOSE)) { body = body.slice(0, -(CLOSE.length + 1)); mode = mode || 'orphan-close'; }
    else if (body.endsWith(CLOSE)) { body = body.slice(0, -CLOSE.length); mode = mode || 'orphan-close'; }
    else if (mode) mode = 'orphan-open';
    if (!mode || body.includes('<%') || body.includes('%>')) return null;
    return {body, mode, content: body};
  }
  function idle() {
    const probe = typeof builtin !== 'undefined' && typeof builtin.duringGenerating === 'function' ? () => builtin.duringGenerating() : typeof TavernHelper !== 'undefined' && typeof TavernHelper.builtin?.duringGenerating === 'function' ? () => TavernHelper.builtin.duringGenerating() : null;
    if (probe && probe() !== false) throw new Error('请先停止生成，再移除人物EJS。');
  }
  function selected() {
    const id = getCurrentCharacterId();
    const book = getCharWorldbookNames().primary;
    if (id == null || !book || typeof book !== 'string') throw new Error('请打开角色，并确认已关联主世界书。');
    return {id, book, key: 'solaris-person-plain-backup-v1:' + id + ':' + book};
  }
  function same(t) { return getCurrentCharacterId() === t.id && getCharWorldbookNames().primary === t.book; }
  async function repair() {
    if (busy) return;
    busy = true;
    try {
      idle(); const t = selected(); const original = await getWorldbook(t.book);
      if (!same(t)) throw new Error('当前角色已切换，请在目标角色重试。');
      const changes = [];
      for (const e of original) {
        if (!NAMES.has(nameOf(e))) continue;
        const parsed = separate(e.content);
        if (parsed) changes.push({uid: idOf(e), name: nameOf(e), before: e.content, after: parsed.content, mode: parsed.mode});
      }
      if (!changes.length) { toastr.info('没有找到可移除的简单EJS包装，普通文本和自定义复杂代码不会被改动。'); return; }
      localStorage.setItem(t.key, JSON.stringify({book: t.book, id: t.id, changes}));
      idle(); if (!same(t)) throw new Error('当前角色已切换，未写入。');
      let written = 0;
      await updateWorldbookWith(t.book, entries => {
        idle(); if (!same(t)) throw new Error('当前角色已切换，未写入。');
        return entries.map(e => {
          const c = changes.find(c => c.uid === idOf(e) && c.name === nameOf(e));
          if (!c || e.content !== c.before) return e;
          written++; return {...e, content: c.after};
        });
      });
      toastr.success('已处理 ' + written + ' 个人物条目，现为纯文本绿灯触发，正文未改。请重新打开提示词查询器验证。');
    } catch (e) { toastr.error(String(e.message || e), '人物词条去EJS'); }
    finally { busy = false; }
  }
  async function restore() {
    if (busy) return;
    busy = true;
    try {
      idle(); const t = selected(); const raw = localStorage.getItem(t.key);
      if (!raw) { toastr.info('当前角色没有去EJS前的备份。'); return; }
      const backup = JSON.parse(raw);
      if (backup.book !== t.book || backup.id !== t.id) throw new Error('备份不属于当前角色，未写入。');
      let restored = 0;
      await updateWorldbookWith(t.book, entries => {
        idle(); if (!same(t)) throw new Error('当前角色已切换，未写入。');
        return entries.map(e => {
          const c = backup.changes.find(c => c.uid === idOf(e) && c.name === nameOf(e));
          if (!c || e.content !== c.after) return e;
          restored++; return {...e, content: c.before};
        });
      });
      toastr.success('已恢复 ' + restored + ' 个未被另行修改的条目包装。');
    } catch (e) { toastr.error(String(e.message || e), '恢复人物包装'); }
    finally { busy = false; }
  }
  eventOn(getButtonEvent('移除人物EJS'), repair);
  eventOn(getButtonEvent('恢复去EJS前备份'), restore);
})();
